{"filePath": "storage.py", "content": "import json

def save_todos(todos):
    """Save a list of todos to todos.json."""
    with open('todos.json', 'w') as f:
        json.dump(todos, f)

def load_todos():
    """Load todos from todos.json, returns empty list if file not found."""
    try:
        with open('todos.json', 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return []"}
